package com.example.starter.batch.dto;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.time.Instant;
import java.util.List;

/**
 * 创建批次请求。producedAt 为 ISO-8601 UTC 时间；requiredTests 为 1～5 个必做检验项。
 * quantity 与 maxSampleQuantity 同时缺省为普通批次（无数量概念）；
 * 同时提供则为新类型整数数量批次：quantity 为正整数总数量，
 * maxSampleQuantity 为不可变最大取样量，取值 0 至 quantity。
 */
public record CreateBatchRequest(
        @NotBlank(message = "commandKey 不能为空") String commandKey,
        @NotBlank(message = "batchKey 不能为空") String batchKey,
        @NotBlank(message = "productCode 不能为空") String productCode,
        @NotBlank(message = "batchNo 不能为空") String batchNo,
        @NotNull(message = "producedAt 不能为空") Instant producedAt,
        @NotNull(message = "requiredTests 不能为空")
        @Size(min = 1, max = 5, message = "requiredTests 必须包含 1～5 个检验项")
        List<@NotBlank(message = "检验项不能为空") String> requiredTests,
        @Min(value = 1, message = "quantity 必须为正整数") Integer quantity,
        @Min(value = 0, message = "maxSampleQuantity 不能为负数") Integer maxSampleQuantity
) {
}

package com.example.starter.batch.dto;

import com.example.starter.batch.TestOutcome;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

/**
 * 提交检验结果请求。testKey 在同一批次内唯一，同内容重放返回原结果，不同内容返回 409。
 * sampleKey 与 consumeQuantity 可选且必须成对出现：仅新类型数量批次可在提交检验时
 * 绑定正整数消耗量；无论检验合格与否都扣量，消费不可撤销。
 */
public record SubmitTestRequest(
        @NotBlank(message = "commandKey 不能为空") String commandKey,
        @NotBlank(message = "testKey 不能为空") String testKey,
        @NotBlank(message = "testItem 不能为空") String testItem,
        @NotNull(message = "result 不能为空，取值为 PASS/FAIL") TestOutcome result,
        @NotBlank(message = "inspector 不能为空") String inspector,
        String sampleKey,
        @Positive(message = "consumeQuantity 必须为正整数") Integer consumeQuantity
) {
}

package com.example.starter.batch.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 拆分请求体。父批由路径给出；children 为 2～5 个全新子批，各自提供全局唯一的
 * batchKey 与批号 batchNo。子批键已存在或请求内重复时整次 409，父批不变。
 * 新类型数量批次拆分时每个子批必须携带正整数 quantity，
 * 且子批数量之和必须等于父批总数量减去累计消耗；普通批次不得携带 quantity。
 */
public record SplitRequest(
        @NotBlank(message = "commandKey 不能为空") String commandKey,
        @NotNull(message = "children 不能为空")
        @Size(min = 2, max = 5, message = "children 必须包含 2～5 个子批")
        List<@Valid ChildSpec> children
) {

    /**
     * 子批规格：batchKey 全局唯一，batchNo 为子批批号；产品编码、生产时间与必做检验项继承父批。
     * quantity 仅新类型数量批次拆分必填（正整数），普通批次必须为 null。
     */
    public record ChildSpec(
            @NotBlank(message = "子批 batchKey 不能为空") String batchKey,
            @NotBlank(message = "子批 batchNo 不能为空") String batchNo,
            @Positive(message = "子批 quantity 必须为正整数") Integer quantity
    ) {
    }
}

